print('Re-searching products for coffee maker under $150...')
page_index=0
page_limit=20
all_products=[]
while True:
    resp = apis.amazon.search_products(
        query='coffee maker',
        min_price=0,
        max_price=150,
        min_product_rating=0,
        max_product_rating=5,
        min_seller_rating=0,
        max_seller_rating=5,
        page_index=page_index,
        page_limit=page_limit,
        sort_by='+rating'
    )
    if not isinstance(resp, list):
        print('Unexpected response type', type(resp))
        break
    print('page', page_index, 'count', len(resp))
    if not resp:
        break
    all_products.extend(resp)
    if len(resp) < page_limit:
        break
    page_index += 1
print('total fetched', len(all_products))

# Dedupe by product_id keeping best rating then best delivery then best price
by_id={}
for p in all_products:
    pid=p['product_id']
    if pid not in by_id:
        by_id[pid]=p
    else:
        cur=by_id[pid]
        if (p.get('rating') or 0) > (cur.get('rating') or 0):
            by_id[pid]=p
        elif (p.get('rating') or 0)==(cur.get('rating') or 0):
            if (p.get('delivery_days') or 1e9) < (cur.get('delivery_days') or 1e9):
                by_id[pid]=p
            elif (p.get('delivery_days') or 1e9)==(cur.get('delivery_days') or 1e9):
                if (p.get('price') or 1e9) < (cur.get('price') or 1e9):
                    by_id[pid]=p
products=list(by_id.values())
print('unique products', len(products))

def norm(s):
    return (s or '').lower()

positive = ['coffee maker','coffee brewer','drip coffee','k-cup','cuisinart','nespresso','espresso machine','espresso','coffee pod']
# keep coffee makers / espresso machines; exclude coffee tables etc
exclude_terms = ['coffee table','waffle maker','popcorn maker','table','latasha coffee table','ikea lack','ikea lunnarp']

cand=[]
for p in products:
    name=norm(p.get('name'))
    desc=norm(p.get('description'))
    text=name+' '+desc
    if any(ex in text for ex in exclude_terms):
